transcripcion.texto:
```json
{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "cocinar rápido",
        "category": "electrodomesticos_cocina",
        "max_price": 399990
      }
    },
    {
      "id": "s2",
      "op": "get_product",
      "args": {
        "id": "P0168"
      }
    },
    {
      "id": "s3",
      "op": "get_reviews",
      "args": {
        "product_id": "P0168",
        "limit": 3
      }
    },
    {
      "id": "s4",
      "op": "respond",
      "plantilla": "Aquí tienes lo que encontré:\n\n**Opciones dentro de tu presupuesto de $399.990:**\n{resultados_busqueda}\n\n---\n\n**Ficha técnica: {nombre_hervidor}**\n- Marca: {marca_hervidor}\n- Precio: ${precio_hervidor}\n- Categoría: {categoria_hervidor}\n- Evaluación promedio: {rating_hervidor}\n- Stock: {stock_hervidor}\n- Atributos: {atributos_hervidor}\n\n**Reseñas de clientes:** {resenas}\n\n<<rec:P0168>>",
      "vars": {
        "resultados_busqueda": "$s1",
        "nombre_hervidor": "$s2.name",
        "marca_hervidor": "$s2.brand",
        "precio_hervidor": "$s2.price_clp",
        "categoria_hervidor": "$s2.category",
        "rating_hervidor": "$s2.avg_rating",
        "stock_hervidor": "$s2.stock",
        "atributos_hervidor": "$s2.attributes",
        "resenas": "$s3"
      }
    }
  ]
}
